    @Test
    void pointsAtTheSubmittedLineOfACompileErrorEvenWhenAHeaderWasAdded() throws IOException {
        String submitted = """
                public class Q1a {
                    public static int count(String input) {
                        for (i = 0; i < input.length(); i++) {
                        }
                        return 0;
                    }
                }
                """;
        // The compiled copy gained a three-line header, so javac's line 6 is line 3 as submitted.
        Path compiled = write("normalized/Q1a.java", "// Name: A\n// Email: a@x\n\n" + submitted);
        Path original = write("original/Q1a.java", submitted);
        ProcessResult javac = failed("/tmp/sources/Q1a.java:6: error: cannot find symbol\n"
                + "        for (i = 0; i < input.length(); i++) {\n             ^\n"
                + "  symbol:   variable i\n  location: class Q1a\n1 error\n");

        List<Feedback> feedback = generate(submission("Q1a", compiled, Map.of("Q1a.java", original)),
                new QuestionGradingResult("Q1a", Status.COMPILATION_ERROR, 0, 0, 0, javac, null, ""));

        assertEquals(1, feedback.size());
        assertEquals("Loop variable not declared", feedback.getFirst().kind());
        assertEquals(3, feedback.getFirst().location().orElseThrow().line());
        assertTrue(feedback.getFirst().message().contains("for (int i = 0"));
    }

