    @Test
    void findsTheScannerLoopThatOnlyAdvancesInsideAnIf() throws IOException {
        Path source = write("Q2a.java", """
                import java.util.*;
                import java.io.*;

                public class Q2a {
                    public static double getAverageAge(String filename, String surname) {
                        int count = 0;
                        try {
                            Scanner s = new Scanner(new FileReader(filename));
                            while (s.hasNextLine()) {
                                if (s.findInLine(surname) != null) {
                                    s.nextLine();
                                    count++;
                                }
                            }
                        } catch (FileNotFoundException e) {
                            return -1;
                        }
                        return count;
                    }
                }
                """);
        String stdout = """
                Test 1: getAverageAge(is442.txt, LEE)
                Expected  :|-1.0|
                Actual    :|-1.0|
                Passed
                Test case 2 skipped: it did not finish within the time limit. Test: getAverageAge(persons.txt, TAY)
                Failed -> Timed out
                """;
        ProcessResult run = new ProcessResult(ProcessResult.Status.TIMED_OUT, 137, stdout, "", Duration.ZERO);

        List<Feedback> feedback = generate(submission("Q2a", source, Map.of()),
                new QuestionGradingResult("Q2a", Status.EXECUTION_TIMEOUT, 1, 1, 0, null, run, ""));

        assertEquals(1, feedback.size());
        assertEquals("Infinite loop", feedback.getFirst().kind());
        assertEquals(9, feedback.getFirst().location().orElseThrow().line());
        assertTrue(feedback.getFirst().message().contains("only moved forward inside an `if`"));
    }

