    @Test
    void diagnosesWrongResultsByComparingExpectedAndActual() {
        assertEquals("Extra items", WrongOutputRule.diagnose("[zoe]", "[ellen, alan, zoe]").kind());
        assertEquals("Missing items", WrongOutputRule.diagnose("[a, b]", "[a]").kind());
        assertEquals("Wrong order", WrongOutputRule.diagnose("[a, b]", "[b, a]").kind());
        assertEquals("Wrong number", WrongOutputRule.diagnose("26.0", "28.0").kind());
        assertEquals("Letter case", WrongOutputRule.diagnose("Jason LEE", "jason lee").kind());
        assertEquals("Empty result", WrongOutputRule.diagnose("[Daniel]", "[]").kind());
        assertEquals("Incomplete result", WrongOutputRule.diagnose("Jason LEE-4.0", "Jason LEE").kind());
    }

    private List<Feedback> generate(SubmissionValidationResult submission, QuestionGradingResult result) {
        return new FeedbackGenerator(new Templates(temporary.resolve("template")))
                .forStudent(submission, new StudentGradingResult(submission.username(), List.of(result)));
    }

    private SubmissionValidationResult submission(String questionId, Path source, Map<String, Path> originals) {
        return new SubmissionValidationResult(temporary, "alice.2026", temporary,
                Map.of(questionId, new QuestionFiles(List.of(source), List.of(), List.of())), List.of(),
                HeaderIdentity.unknown(), List.of(), originals);
    }

    private static QuestionGradingResult graded(String questionId, String stdout, String stderr) {
        ProcessResult run = new ProcessResult(ProcessResult.Status.EXITED, 0, stdout, stderr, Duration.ZERO);
        return new QuestionGradingResult(questionId, Status.GRADED, 0, 0, 1, null, run, "");
    }

    private static ProcessResult failed(String stderr) {
        return new ProcessResult(ProcessResult.Status.EXITED, 1, "", stderr, Duration.ZERO);
    }

    private Path write(String name, String content) throws IOException {
        Path file = temporary.resolve(name);
        Files.createDirectories(file.getParent());
        return Files.writeString(file, content);
    }
